'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { useRouter } from 'next/navigation'

export default function ReservasPublicaPage() {
  const [canchas, setCanchas] = useState<any[]>([])
  const [complejos, setComplejos] = useState<any[]>([])
  const [complejoSeleccionado, setComplejoSeleccionado] = useState<any>(null)
  const [canchaSeleccionada, setCanchaSeleccionada] = useState<any>(null)
  const [fecha, setFecha] = useState('')
  const [slots, setSlots] = useState<any[]>([])
  const [slotSeleccionado, setSlotSeleccionado] = useState<string | null>(null)
  const [paso, setPaso] = useState(1)
  const [form, setForm] = useState({
    nombre: '',
    telefono: '',
    email: '',
    metodo_pago: 'transferencia',
  })
  const [loading, setLoading] = useState(false)
  const [reservaExitosa, setReservaExitosa] = useState(false)
  const [esDesafio, setEsDesafio] = useState(false)
  const [jugadoresNecesarios, setJugadoresNecesarios] = useState(6)
  const supabase = createClient()

  useEffect(() => {
    cargarComplejos()
  }, [])

  const cargarComplejos = async () => {
    const { data } = await supabase.from('complejos').select('*')
    setComplejos(data || [])
    if (data && data.length === 1) {
      setComplejoSeleccionado(data[0])
      cargarCanchas(data[0].id)
    }
  }

  const cargarCanchas = async (complejoId: string) => {
    const { data } = await supabase
      .from('canchas')
      .select('*')
      .eq('complejo_id', complejoId)
      .eq('activa', true)
    setCanchas(data || [])
  }

  // --- FUNCIÓN ACTUALIZADA ---
  const cargarSlots = async () => {
    if (!canchaSeleccionada || !fecha) return
    setLoading(true)

    // 1. Leemos el horario de la CANCHA (con fallback si es nulo)
    // Usamos el operador ?? para asegurar que siempre haya un string de hora
    const aperturaRaw = canchaSeleccionada.horario_apertura ?? "08:00:00"
    const cierreRaw = canchaSeleccionada.horario_cierre ?? "23:00:00"

    // Limpiamos los segundos por si vienen de la DB (ej: "08:00:00" -> "08:00")
    const apertura = aperturaRaw.slice(0, 5)
    const cierre = cierreRaw.slice(0, 5)

    // 2. Buscamos reservas existentes
    const { data: reservasExistentes } = await supabase
      .from('reservas')
      .select('hora_inicio')
      .eq('cancha_id', canchaSeleccionada.id)
      .eq('fecha', fecha)
      .neq('estado', 'cancelada')

    const ocupados = reservasExistentes?.map(r => r.hora_inicio.slice(0, 5)) || []

    const slotsGenerados = []
    let hora = parseInt(apertura.split(':')[0])
    let horaFin = parseInt(cierre.split(':')[0])

    // Seguridad: si el horario de cierre es menor al de apertura, ponemos 23hs
    if (horaFin <= hora) horaFin = 23

    while (hora < horaFin) {
      const horaStr = `${hora.toString().padStart(2, '0')}:00`
      const horaFinStr = `${(hora + 1).toString().padStart(2, '0')}:00`
      slotsGenerados.push({
        hora_inicio: horaStr,
        hora_fin: horaFinStr,
        disponible: !ocupados.includes(horaStr),
      })
      hora++
    }

    setSlots(slotsGenerados)
    setPaso(3)
    setLoading(false)
  }

  const handleReservar = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)

    const slotElegido = slots.find(s => s.hora_inicio === slotSeleccionado)
    const monto_total = canchaSeleccionada.precio_hora
    const monto_seña = monto_total / 2

    if (esDesafio) {
      await supabase.from('desafios').insert({
        cancha_id: canchaSeleccionada.id,
        complejo_id: complejoSeleccionado.id,
        fecha,
        hora_inicio: slotElegido.hora_inicio,
        hora_fin: slotElegido.hora_fin,
        equipo_creador_nombre: form.nombre,
        equipo_creador_telefono: form.telefono,
        jugadores_necesarios: jugadoresNecesarios,
        estado: 'abierto',
      })
    } else {
      await supabase.from('reservas').insert({
        cancha_id: canchaSeleccionada.id,
        complejo_id: complejoSeleccionado.id,
        fecha,
        hora_inicio: slotElegido.hora_inicio,
        hora_fin: slotElegido.hora_fin,
        cliente_nombre: form.nombre,
        cliente_telefono: form.telefono,
        cliente_email: form.email,
        monto_seña,
        monto_total,
        metodo_pago: form.metodo_pago,
        estado: 'pendiente',
        es_desafio: false,
      })
    }

    setReservaExitosa(true)
    setLoading(false)
  }

  const tipoLabel: Record<string, string> = {
    futbol_5: '⚽ Fútbol 5',
    futbol_7: '⚽ Fútbol 7',
    futbol_11: '⚽ Fútbol 11',
    paddle: '🎾 Pádel',
  }

  if (reservaExitosa) {
    return (
      <main className="min-h-screen bg-green-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl p-10 text-center max-w-md w-full">
          <p className="text-6xl mb-4">🎉</p>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">
            {esDesafio ? '¡Desafío creado!' : '¡Reserva enviada!'}
          </h2>
          <p className="text-gray-500 mb-6">
            {esDesafio 
              ? 'Tu desafío está visible. Te avisaremos cuando alguien lo acepte.' 
              : 'Te contactaremos por WhatsApp para confirmar el pago de la seña.'}
          </p>
          <button
            onClick={() => window.location.reload()}
            className="bg-green-600 text-white px-8 py-3 rounded-xl font-bold w-full hover:bg-green-700 transition"
          >
            Volver a inicio
          </button>
        </div>
      </main>
    )
  }

  return (
    <main className="min-h-screen bg-gray-50 pb-20">
      <nav className="bg-white shadow-sm px-6 py-4 flex justify-between items-center mb-6">
        <h1 className="text-xl font-bold text-green-700">⚽ Reservá tu cancha</h1>
      </nav>

      <div className="container mx-auto px-4 max-w-xl">

        {/* Paso 1 - Elegir cancha */}
        <div className="mb-8">
          <h2 className="text-lg font-bold text-gray-700 mb-4">1️⃣ Elegí una cancha</h2>
          <div className="grid grid-cols-1 gap-3">
            {canchas.map((cancha) => (
              <button
                key={cancha.id}
                onClick={() => { setCanchaSeleccionada(cancha); setPaso(2) }}
                className={`p-4 rounded-xl border-2 text-left transition ${canchaSeleccionada?.id === cancha.id ? 'border-green-500 bg-green-50 shadow-md' : 'border-white bg-white hover:border-green-200'}`}
              >
                <p className="font-bold text-gray-800">{cancha.nombre}</p>
                <p className="text-sm text-gray-500">{tipoLabel[cancha.tipo]}</p>
                <p className="text-sm text-green-600 font-bold mt-1">${cancha.precio_hora.toLocaleString()}/hora</p>
              </button>
            ))}
          </div>
        </div>

        {/* Paso 2 - Elegir fecha */}
        {paso >= 2 && (
          <div className="mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h2 className="text-lg font-bold text-gray-700 mb-4">2️⃣ Elegí una fecha</h2>
            <div className="flex gap-3">
              <input
                type="date"
                value={fecha}
                min={new Date().toISOString().split('T')[0]}
                onChange={(e) => setFecha(e.target.value)}
                className="flex-1 border-2 border-white bg-white rounded-xl px-4 py-3 focus:outline-none focus:border-green-500 shadow-sm"
              />
              <button
                onClick={cargarSlots}
                disabled={!fecha || loading}
                className="bg-green-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-green-700 transition disabled:opacity-50"
              >
                {loading ? '...' : 'Ver horarios'}
              </button>
            </div>
          </div>
        )}

        {/* Paso 3 - Elegir horario */}
        {paso >= 3 && (
          <div className="mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h2 className="text-lg font-bold text-gray-700 mb-4">3️⃣ Elegí un horario</h2>
            <div className="grid grid-cols-3 gap-2">
              {slots.map((slot) => (
                <button
                  key={slot.hora_inicio}
                  disabled={!slot.disponible}
                  onClick={() => { setSlotSeleccionado(slot.hora_inicio); setPaso(4) }}
                  className={`py-3 rounded-xl text-sm font-bold transition ${
                    !slot.disponible ? 'bg-gray-100 text-gray-400 cursor-not-allowed' :
                    slotSeleccionado === slot.hora_inicio ? 'bg-green-600 text-white shadow-lg' :
                    'bg-white border-2 border-transparent text-gray-700 hover:border-green-400 shadow-sm'
                  }`}
                >
                  {slot.hora_inicio}
                  {!slot.disponible && <span className="block text-[10px] uppercase">Ocupado</span>}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Paso 4 - Datos del cliente */}
        {paso >= 4 && slotSeleccionado && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h2 className="text-lg font-bold text-gray-700 mb-4">4️⃣ Completá tus datos</h2>
            <form onSubmit={handleReservar} className="bg-white rounded-2xl shadow-xl p-6 space-y-4 border border-gray-100">
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">
                  {esDesafio ? 'Nombre de tu equipo' : 'Nombre y apellido'}
                </label>
                <input
                  type="text"
                  value={form.nombre}
                  onChange={(e) => setForm({ ...form, nombre: e.target.value })}
                  required
                  className="w-full bg-gray-50 border-2 border-gray-50 rounded-xl px-4 py-3 focus:outline-none focus:border-green-500 transition"
                  placeholder={esDesafio ? "Los Cracks FC" : "Juan García"}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">WhatsApp</label>
                <input
                  type="tel"
                  value={form.telefono}
                  onChange={(e) => setForm({ ...form, telefono: e.target.value })}
                  required
                  className="w-full bg-gray-50 border-2 border-gray-50 rounded-xl px-4 py-3 focus:outline-none focus:border-green-500 transition"
                  placeholder="1123456789"
                />
              </div>

              <div className="border-t border-gray-100 pt-4">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <input
                    type="checkbox"
                    checked={esDesafio}
                    onChange={(e) => setEsDesafio(e.target.checked)}
                    className="w-5 h-5 text-green-600 border-gray-300 rounded focus:ring-green-500 transition"
                  />
                  <span className="text-sm font-bold text-gray-600 group-hover:text-green-600 transition">⚔️ Crear como desafío (busco rival)</span>
                </label>
              </div>

              <div className="bg-green-50 rounded-xl p-4 border border-green-100">
                <p className="text-green-800 font-bold text-sm mb-1">Resumen:</p>
                <p className="text-green-700 text-xs">🏟️ {canchaSeleccionada?.nombre} · {fecha} · {slotSeleccionado} hs</p>
                <p className="text-green-800 font-black mt-2">
                  Total: ${canchaSeleccionada?.precio_hora.toLocaleString()}
                </p>
              </div>

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-green-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-green-700 transition shadow-lg shadow-green-200 disabled:opacity-50"
              >
                {loading ? 'Enviando...' : esDesafio ? '⚔️ Crear desafío' : '✅ Confirmar reserva'}
              </button>
            </form>
          </div>
        )}
      </div>
    </main>
  )
}